import { CliSignal, parseCommandLine } from "./lib/cli/parseArgs.mjs";
import { getProgramName } from "./lib/cli/programText.mjs";
import { createBiLookup } from "./lib/core/biLookup.mjs";
import { toPythonBooleanString } from "./lib/core/pythonBoolean.mjs";

export function main(argv = process.argv) {
  const programName = getProgramName(argv[1]);
  let args;

  try {
    args = parseCommandLine(argv.slice(2), programName);
  } catch (error) {
    if (error instanceof CliSignal) {
      const stream = error.stream === "stdout" ? process.stdout : process.stderr;
      stream.write(error.output);
      process.exitCode = error.exitCode;
      return;
    }

    throw error;
  }

  const lookup = createBiLookup([
    ["a", "1"],
    ["b", "2"],
    ["c", "3"],
  ]);

  process.stdout.write(`${toPythonBooleanString(lookup.hasKey(args.key))}\n`);
  process.stdout.write(`${toPythonBooleanString(lookup.hasValue(args.val))}\n`);
}

main();

